#!/usr/bin/env python3
from pathlib import Path

C1=Path('scripts/app-src/controller-part-01.part.js')
C5=Path('scripts/app-src/controller-part-05.part.js')
C6=Path('scripts/app-src/controller-part-06.part.js')
CSS=Path('styles/app-src/styles-part-01.part.css')

c1=C1.read_text(encoding='utf-8')
c5=C5.read_text(encoding='utf-8')
c6=C6.read_text(encoding='utf-8')
css=CSS.read_text(encoding='utf-8')

def swap(text,old,new,label):
    n=text.count(old)
    if n!=1: raise SystemExit(f'Safety stop: {label} expected 1 exact owner, found {n}')
    print('replaced',label)
    return text.replace(old,new,1)

# Extend the existing HUD owner. Do not create a second phone-down state machine.
old_decl="let hudFlags=typeof MTGPlayerHUD!=='undefined'?MTGPlayerHUD.loadFlags(localStorage):{newPlayerHud:true,contextualActions:true,lowAttention:true,universalNumeric:true,spatialOpponents:true,quickCommanderDamage:true,eventBasedInput:true,quickActionIntelligence:true,criticalStateAwareness:true,opponentDetailDrawer:true,battlefieldQuickActions:true,smartResourceRail:true,deckAdaptiveHud:true},forcedHudAwakeUntil=0,playerHudPage='home',battlefieldViewPlayer='all';"
new_decl="let hudFlags=typeof MTGPlayerHUD!=='undefined'?MTGPlayerHUD.loadFlags(localStorage):{newPlayerHud:true,contextualActions:true,lowAttention:true,universalNumeric:true,spatialOpponents:true,quickCommanderDamage:true,eventBasedInput:true,quickActionIntelligence:true,criticalStateAwareness:true,opponentDetailDrawer:true,battlefieldQuickActions:true,smartResourceRail:true,deckAdaptiveHud:true},forcedHudAwakeUntil=0,forcedHudAwakeTimer=null,companionAttentionKey='',playerHudPage='home',battlefieldViewPlayer='all';"
c1=swap(c1,old_decl,new_decl,'phone-down timer state')

old_wake="function hudForcedAwake(){return Date.now()<forcedHudAwakeUntil}\nfunction wakePlayerHud(ms=30000){forcedHudAwakeUntil=Date.now()+ms;refreshContextHud();}"
new_wake="function hudForcedAwake(){return Date.now()<forcedHudAwakeUntil}\nfunction wakePlayerHud(ms=30000){ms=Math.max(1500,Number(ms)||30000);forcedHudAwakeUntil=Date.now()+ms;clearTimeout(forcedHudAwakeTimer);$('game')?.classList.remove('lowAttention');refreshContextHud();forcedHudAwakeTimer=setTimeout(()=>{forcedHudAwakeUntil=0;forcedHudAwakeTimer=null;refreshContextHud()},ms+80)}\nfunction companionAttentionState(ctx,priorityView){let reasons=[];if(priorityView?.isHolder||ctx?.hasPriority)reasons.push('priority');if(hudFlags.criticalStateAwareness&&typeof MTGPlayerAlerts!=='undefined'){try{if(MTGPlayerAlerts.evaluate(st,me)?.critical)reasons.push('critical')}catch{}}if(assistEnabled()&&typeof MTGAssistMode!=='undefined'){try{let v=MTGAssistMode.evaluate({enabled:true,state:st,players,playerId:me,profile:prof,dismissedKeys:Object.keys(assistHistory.dismissed||{}),seenKeys:Object.keys(assistHistory.seen||{})});if(v?.show&&(v.urgent||v.attention==='required'))reasons.push('assist')}catch{}}let modalOpen=$('modal')&&!$('modal').classList.contains('h');if(modalOpen)reasons.push('dialog');return{required:reasons.length>0,key:reasons.join('|'),reasons}}"
c5=swap(c5,old_wake,new_wake,'manual wake expiry and attention guard')

old_refresh="function refreshContextHud(){if(typeof MTGPlayerHUD==='undefined'||!$('game'))return;let ctx=MTGPlayerHUD.context(st,me),base=hudFlags.contextualActions?MTGPlayerHUD.actionsFor(st,me):[{id:'cast',label:'CAST'},{id:'respond',label:'ACTION'},{id:'pass',label:'PASS'},{id:'more',label:'•••'}],priorityView=typeof MTGSmartPriority!=='undefined'?MTGSmartPriority.view(st,players,me):null,actions=typeof MTGSmartPriority!=='undefined'?MTGSmartPriority.controls(st,players,me,base):base,buttons=[$('cast'),$('resp'),$('pass'),$('more')];buttons.forEach((b,i)=>{let a=actions[i];if(!b)return;let blocked=!a||a.id==='wait';b.disabled=blocked;b.textContent=a?.label||'—';b.dataset.contextAction=a?.id||'';b.classList.toggle('dkPrimary',i===0&&!!a&&!blocked);b.classList.toggle('waitingAction',a?.id==='wait')});$('game').classList.toggle('hudModern',!!hudFlags.newPlayerHud);$('lifeMinus')?.classList.toggle('h',!hudFlags.universalNumeric);$('lifePlus')?.classList.toggle('h',!hudFlags.universalNumeric);let low=!!hudFlags.newPlayerHud&&!!hudFlags.lowAttention&&MTGPlayerHUD.lowAttention(st,me,{forcedAwake:hudForcedAwake()});$('game').classList.toggle('lowAttention',low);$('hudWakeBtn')?.classList.toggle('h',!low);let mode=ctx.stackActive?'stack':ctx.isActive?ctx.phaseGroup:'opponent',ph=$('contextHint'),hud=document.querySelector('.playerHud');if(hud)hud.dataset.context=mode;let director=typeof MTGSmartPriority!=='undefined'?MTGSmartPriority.director(st,players,me):null,mount=$('priorityDirector');if(mount&&director){mount.classList.toggle('h',!director.show);mount.classList.toggle('mine',!!director.isHolder);mount.classList.toggle('waiting',!!director.hasWindow&&!director.isHolder);let total=Math.max(0,director.passTotal||0),done=Math.max(0,director.passCount||0);mount.innerHTML=director.show?'<div class=\"priorityDirectorTop\"><div class=\"priorityDirectorTitle\">'+esc(director.title)+'</div><div class=\"priorityDirectorMode\">'+esc(director.mode.toUpperCase())+'</div></div><div class=\"priorityDirectorDetail\">'+esc(director.detail)+'</div>'+(total?'<div class=\"priorityPassTrack\">'+Array.from({length:total},(_,i)=>'<span class=\"priorityPassDot '+(i<done?'done':i===done&&director.hasWindow?'current':'')+'\"></span>').join('')+'</div>':''):''}if(ph){if(priorityView?.hasWindow)ph.textContent=priorityView.isHolder?'PRIORITY · YOUR DECISION':'PRIORITY · WAITING FOR P'+priorityView.holder;else if(ctx.stackActive)ph.textContent='STACK · '+ctx.stackSize+' OBJECT'+(ctx.stackSize===1?'':'S');else if(ctx.isActive)ph.textContent=ctx.phase.toUpperCase()+' · '+(priorityView?.mode==='full'?'PHASE CLEARED':'YOUR TURN');else ph.textContent=ctx.hasPriority?'YOU HAVE PRIORITY':'OPPONENT TURN · LOW ATTENTION READY'}renderAssistCoach()}"
new_refresh="function refreshContextHud(){if(typeof MTGPlayerHUD==='undefined'||!$('game'))return;let ctx=MTGPlayerHUD.context(st,me),base=hudFlags.contextualActions?MTGPlayerHUD.actionsFor(st,me):[{id:'cast',label:'CAST'},{id:'respond',label:'ACTION'},{id:'pass',label:'PASS'},{id:'more',label:'•••'}],priorityView=typeof MTGSmartPriority!=='undefined'?MTGSmartPriority.view(st,players,me):null,actions=typeof MTGSmartPriority!=='undefined'?MTGSmartPriority.controls(st,players,me,base):base,buttons=[$('cast'),$('resp'),$('pass'),$('more')];buttons.forEach((b,i)=>{let a=actions[i];if(!b)return;let blocked=!a||a.id==='wait';b.disabled=blocked;b.textContent=a?.label||'—';b.dataset.contextAction=a?.id||'';b.classList.toggle('dkPrimary',i===0&&!!a&&!blocked);b.classList.toggle('waitingAction',a?.id==='wait')});$('game').classList.toggle('hudModern',!!hudFlags.newPlayerHud);$('lifeMinus')?.classList.toggle('h',!hudFlags.universalNumeric);$('lifePlus')?.classList.toggle('h',!hudFlags.universalNumeric);let attention=companionAttentionState(ctx,priorityView),lowCandidate=!!hudFlags.newPlayerHud&&!!hudFlags.lowAttention&&MTGPlayerHUD.lowAttention(st,me,{forcedAwake:hudForcedAwake()}),low=lowCandidate&&!attention.required;$('game').classList.toggle('lowAttention',low);$('game').classList.toggle('companionAttention',attention.required);let wake=$('hudWakeBtn');wake?.classList.toggle('h',!low);if(wake&&low)wake.textContent='SIDEKICK MONITORING · TAP FOR CONTROLS';if(attention.key&&attention.key!==companionAttentionKey){companionAttentionKey=attention.key;$('game').classList.add('companionAttentionPulse');setTimeout(()=>$('game')?.classList.remove('companionAttentionPulse'),900)}else if(!attention.key)companionAttentionKey='';let mode=ctx.stackActive?'stack':ctx.isActive?ctx.phaseGroup:'opponent',ph=$('contextHint'),hud=document.querySelector('.playerHud');if(hud)hud.dataset.context=mode;let director=typeof MTGSmartPriority!=='undefined'?MTGSmartPriority.director(st,players,me):null,mount=$('priorityDirector');if(mount&&director){mount.classList.toggle('h',!director.show);mount.classList.toggle('mine',!!director.isHolder);mount.classList.toggle('waiting',!!director.hasWindow&&!director.isHolder);let total=Math.max(0,director.passTotal||0),done=Math.max(0,director.passCount||0);mount.innerHTML=director.show?'<div class=\"priorityDirectorTop\"><div class=\"priorityDirectorTitle\">'+esc(director.title)+'</div><div class=\"priorityDirectorMode\">'+esc(director.mode.toUpperCase())+'</div></div><div class=\"priorityDirectorDetail\">'+esc(director.detail)+'</div>'+(total?'<div class=\"priorityPassTrack\">'+Array.from({length:total},(_,i)=>'<span class=\"priorityPassDot '+(i<done?'done':i===done&&director.hasWindow?'current':'')+'\"></span>').join('')+'</div>':''):''}if(ph){if(priorityView?.hasWindow)ph.textContent=priorityView.isHolder?'PRIORITY · YOUR DECISION':'PRIORITY · WAITING FOR P'+priorityView.holder;else if(ctx.stackActive)ph.textContent='STACK · '+ctx.stackSize+' OBJECT'+(ctx.stackSize===1?'':'S');else if(ctx.isActive)ph.textContent=ctx.phase.toUpperCase()+' · '+(priorityView?.mode==='full'?'PHASE CLEARED':'YOUR TURN');else ph.textContent=ctx.hasPriority?'YOU HAVE PRIORITY':low?'SIDEKICK MONITORING · OPPONENT TURN':'OPPONENT TURN · CONTROLS OPEN'}renderAssistCoach()}"
c6=swap(c6,old_refresh,new_refresh,'companion-aware HUD state')

# Clean existing visibility owners instead of stacking overrides.
css=swap(css,'.battleScreen.lowAttention .hudWakeBtn{display:block!important}', '.battleScreen.lowAttention .hudWakeBtn{display:block}', 'wake button visibility owner')
css=swap(css,'.battleScreen.lowAttention .playerHud{margin-top:7vh}', '.battleScreen.lowAttention .playerHud{max-width:560px;margin:6vh auto 10px}', 'passive HUD placement')
css=swap(css,'.battleScreen.lowAttention .lifeStage{padding:22px 0}', '.battleScreen.lowAttention .lifeStage{padding:28px 0 22px}', 'passive life emphasis')
css=swap(css,'.battleScreen.lowAttention .battlePageHead{opacity:.7}', '.battleScreen.lowAttention .battlePageHead{opacity:.48;transition:opacity .24s}', 'passive page chrome')
css=swap(css,'.battleScreen.lowAttention .playerHud.criticalHud .hudCriticalBanner{display:flex!important}', '.battleScreen.lowAttention .playerHud.criticalHud .hudCriticalBanner{display:flex}', 'critical banner low-attention visibility')

# Replace the canonical wake button owner with Sidekick-passive styling.
old_btn='.hudWakeBtn{border:1px solid #31506a;background:#09151e;color:#dceaf3;border-radius:999px;padding:8px 13px;font-size:9px;font-weight:900;margin:7px auto 0}'
new_btn='.hudWakeBtn{border:1px solid color-mix(in srgb,var(--deck-a,#52b8ff) 44%,#31506a);background:color-mix(in srgb,var(--deck-a,#52b8ff) 7%,#071018);color:#dceaf3;border-radius:999px;padding:9px 15px;font-size:8px;font-weight:950;letter-spacing:.085em;margin:9px auto 0;box-shadow:0 0 18px color-mix(in srgb,var(--deck-glow,rgba(82,184,255,.2)) 28%,transparent)}'
css=swap(css,old_btn,new_btn,'wake button canonical style')

# Genuine state variants, tied to the existing game owner rather than a new mode.
anchor='.battleScreen.lowAttention .statusRail{opacity:.88}'
companion='.battleScreen.lowAttention .hudIdentity{opacity:.82}.battleScreen.lowAttention .turnStrip{opacity:.72}.battleScreen.lowAttention .priorityDirector{opacity:.84}.battleScreen.companionAttention .playerHud{border-color:color-mix(in srgb,var(--deck-a,#52b8ff) 62%,#d8f4ff);box-shadow:0 18px 44px rgba(0,0,0,.26),0 0 38px color-mix(in srgb,var(--deck-glow,rgba(82,184,255,.2)) 58%,transparent)}.battleScreen.companionAttentionPulse .playerHud{animation:companionWakePulse .85s ease-out}@keyframes companionWakePulse{0%{transform:scale(.992);filter:brightness(1)}35%{transform:scale(1);filter:brightness(1.16)}100%{transform:scale(1);filter:brightness(1)}}@media(prefers-reduced-motion:reduce){.battleScreen.companionAttentionPulse .playerHud{animation:none}}'
if css.count(anchor)!=1: raise SystemExit('Safety stop: passive HUD anchor missing')
css=css.replace(anchor,anchor+companion,1)

# Ownership and behavioral invariants.
for forbidden in ('hudWakeBtn{display:block!important}','criticalHud .hudCriticalBanner{display:flex!important}'):
    if forbidden in css: raise SystemExit('Safety stop: stale stacked phone-down override remains: '+forbidden)
if c5.count('function wakePlayerHud(')!=1 or c5.count('function companionAttentionState(')!=1: raise SystemExit('Safety stop: phone-down JS ownership duplicated')
if c6.count('function refreshContextHud()')!=1: raise SystemExit('Safety stop: context HUD owner duplicated')
if 'forcedHudAwakeTimer=setTimeout' not in c5: raise SystemExit('Safety stop: manual wake does not schedule re-collapse')

C1.write_text(c1,encoding='utf-8')
C5.write_text(c5,encoding='utf-8')
C6.write_text(c6,encoding='utf-8')
CSS.write_text(css,encoding='utf-8')
print('Phone-down companion pass applied to existing low-attention owner')
